// Filter Scanner Workflow
// Extracts DQL filter expressions (and matcher values for workflow/openpipeline)
// from all configuration categories. Uploads one lookup table per category
// and a summary with size/length statistics.

import { credentialVaultClient, settingsObjectsClient } from '@dynatrace-sdk/client-classic-environment-v2';
import { execution } from '@dynatrace-sdk/automation-utils';
import { getEnvironmentUrl } from '@dynatrace-sdk/app-environment';
import { lookupDataClient } from '@dynatrace-sdk/client-resource-store';

const TOKEN_URL = 'https://sso.dynatrace.com/sso/oauth2/token';
const REQUIRED_SCOPES = [
  'settings:objects:read',
  'document:documents:read',
  'document:documents:admin',
  'slo:slos:read',
  'automation:workflows:read',
  'storage:files:read',
  'storage:files:write',
].join(' ');

const LOOKUP_PATHS = {
  dashboard:           '/lookups/scanner-service-configuration/filter-dashboard',
  notebook:            '/lookups/scanner-service-configuration/filter-notebook',
  'anomaly-detection': '/lookups/scanner-service-configuration/filter-anomaly-detection',
  slo:                 '/lookups/scanner-service-configuration/filter-slo',
  sre:                 '/lookups/scanner-service-configuration/filter-sre',
  workflow:            '/lookups/scanner-service-configuration/filter-workflow',
  openpipeline:        '/lookups/scanner-service-configuration/filter-openpipeline',
  summary:             '/lookups/scanner-service-configuration/filter-summary',
};

// ── HTTP helper ───────────────────────────────────────────────────────────────
async function dtGet(url, token) {
  const resp = await fetch(url, {
    headers: { authorization: `Bearer ${token}`, accept: 'application/json' },
  });
  if (resp.status === 404) return null;
  if (!resp.ok) throw new Error(`${resp.status}: ${url}`);
  return resp.json();
}

async function dtPost(url, token, body) {
  const resp = await fetch(url, {
    method: 'POST',
    headers: { authorization: `Bearer ${token}`, accept: 'application/json', 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!resp.ok) throw new Error(`${resp.status}: ${url}`);
  return resp.json();
}

// ── Walk object tree, collect all string values ───────────────────────────────
function collectStrings(value, out = []) {
  if (typeof value === 'string') {
    out.push(value);
  } else if (Array.isArray(value)) {
    for (const item of value) collectStrings(item, out);
  } else if (value !== null && typeof value === 'object') {
    for (const v of Object.values(value)) collectStrings(v, out);
  }
  return out;
}

// ── Walk object tree, collect all "matcher" field values ──────────────────────
function collectMatchers(value, out = []) {
  if (value === null || typeof value !== 'object') return out;
  if (Array.isArray(value)) {
    for (const item of value) collectMatchers(item, out);
  } else {
    for (const [k, v] of Object.entries(value)) {
      if (k === 'matcher' && typeof v === 'string' && v.trim()) {
        out.push(v.trim());
      } else {
        collectMatchers(v, out);
      }
    }
  }
  return out;
}

// ── Extract filter expressions (+ optional matcher values) ────────────────────

// ── Strip lines where // precedes the filter keyword ─────────────────────────
function stripCommentedLines(str) {
  return str.split('\n').map(function(line) {
    var ci = line.indexOf('//');
    if (ci === -1) return line;
    var fi = line.search(/\bfilter\b/i);
    if (fi === -1) return line;
    return ci < fi ? '' : line;
  }).join('\n');
}

// C-helper: depth-tracking extractor for filter: <expr> (not { )
// Comma is a separator only at paren-depth 0 (so matchesPhrase(id,"...") is captured whole)
function extractFilterCExprs(str) {
  var re = /\bfilter\s*:\s*(?!\{)/gi;
  var results = [];
  var m;
  while ((m = re.exec(str)) !== null) {
    var i = re.lastIndex;
    while (i < str.length && str[i] === ' ') i++;
    if (i >= str.length || str[i] === '{') continue;
    var depth = 0;
    var start = i;
    while (i < str.length) {
      var c = str[i];
      if (c === '(' || c === '[') { depth++; i++; }
      else if (c === ')' || c === ']') {
        if (depth === 0) { i++; break; }
        depth--;
        i++;
        if (depth === 0) break;
      }
      else if (depth === 0 && (c === ',' || c === '|')) { break; }
      else { i++; }
    }
    var expr = str.slice(start, i).trim();
    if (expr.length >= 2) results.push(expr);
    re.lastIndex = i;
  }
  return results;
}
function extractFilters(body, includeMatchers = false) {
  const seen    = new Set();
  const filters = [];

  function add(raw) {
    const expr = raw
      .replace(/\n\s*/g, ' ')  // newline = continuation → space
      .replace(/\\"/g, '"')    // unescape \" → "
      .trim();
    if (expr.length >= 2 && !seen.has(expr)) {
      seen.add(expr);
      filters.push(expr);
    }
  }

  for (const str of collectStrings(body)) {
    if (!str.includes('filter')) continue;
    const cleaned = stripCommentedLines(str);
    if (!cleaned.includes('filter')) continue;
    // A: filter <expr>  (no colon) — stop at , | end; newline = continuation
    for (const m of cleaned.matchAll(/\bfilter(?!\s*:)\s+([^\r\n]+?)(?=\s*\||$)/gi)) add(m[1]);
    // B: filter: { ... } / filter : { ... }  — stop at first }
    for (const m of cleaned.matchAll(/\bfilter\s*:\s*(\{[^}]+\})/gi)) add(m[1]);
    // C: filter: expr / filter : expr  (no curly) — comma is separator at paren-depth 0
    for (const expr of extractFilterCExprs(cleaned)) add(expr);
  }

  if (includeMatchers) {
    for (const v of collectMatchers(body)) add(v);
  }

  return filters;
}

// ── Build one lookup record ───────────────────────────────────────────────────
function buildRecord(category, id, name, body, timestamp, includeMatchers = false) {
  const filters     = extractFilters(body, includeMatchers);
  const filtersJson = JSON.stringify(filters);
  return {
    configuration_id:    id,
    configuration_type:  category,
    configuration_name:  name,
    filter_count:        filters.length,
    filters:             filtersJson,
    filters_json_length: filtersJson.length,
    scan_timestamp:      timestamp,
  };
}

// ── Empty sentinel (clears stale data when category has 0 results) ────────────
function buildSentinel(category, timestamp) {
  return {
    configuration_id:    '__empty__',
    configuration_type:  category,
    configuration_name:  '',
    filter_count:        0,
    filters:             '[]',
    filters_json_length: 0,
    scan_timestamp:      timestamp,
  };
}

// ── Summary record ────────────────────────────────────────────────────────────
function buildSummaryRecord(category, s, timestamp) {
  return {
    configuration_type:       category,
    total_analyzed:           s.analyzed,
    with_filters:             s.withFilters,
    total_filter_expressions: s.totalExpressions,
    avg_filters_json_length:  s.withFilters > 0 ? Math.round(s.totalLen / s.withFilters) : 0,
    max_filters_json_length:  s.maxLen,
    estimated_file_size_bytes: s.totalLen,
    error_count:              s.errorCount,
    scan_timestamp:           timestamp,
  };
}

function emptyStats() {
  return { analyzed: 0, withFilters: 0, totalExpressions: 0, totalLen: 0, maxLen: 0, errorCount: 0 };
}

function trackRecord(stats, record) {
  if (record.filter_count > 0) {
    stats.withFilters++;
    stats.totalExpressions += record.filter_count;
    stats.totalLen  += record.filters_json_length;
    stats.maxLen     = Math.max(stats.maxLen, record.filters_json_length);
  }
}

// ── Lookup upload ─────────────────────────────────────────────────────────────
async function uploadLookup(records, category) {
  await lookupDataClient.upload({
    body: {
      content: new Blob([records.map(r => JSON.stringify(r)).join('\n')], { type: 'text/plain' }),
      request: {
        filePath:    LOOKUP_PATHS[category],
        parsePattern: 'JSON:json',
        lookupField: 'configuration_id',
        overwrite:   true,
        autoFlatten: true,
        displayName: `Filter Scanner: ${category}`,
      },
    },
  });
  console.log(`Uploaded ${LOOKUP_PATHS[category]} (${records.length} records)`);
}

async function uploadSummary(records) {
  await lookupDataClient.upload({
    body: {
      content: new Blob([records.map(r => JSON.stringify(r)).join('\n')], { type: 'text/plain' }),
      request: {
        filePath:    LOOKUP_PATHS.summary,
        parsePattern: 'JSON:json',
        lookupField: 'configuration_type',
        overwrite:   true,
        autoFlatten: true,
        displayName: 'Filter Scanner: summary',
      },
    },
  });
  console.log(`Uploaded ${LOOKUP_PATHS.summary} (${records.length} records)`);
}

async function readSummary(envUrl, token) {
  try {
    const result = await dtPost(
      `${envUrl}/platform/storage/query/v1/query:execute`,
      token,
      { query: `load "${LOOKUP_PATHS.summary}"`, requestTimeoutMs: 10000 }
    );
    return result?.result?.records ?? [];
  } catch {
    return [];
  }
}

// ── Batch processor ───────────────────────────────────────────────────────────
async function batchProcess(items, fn, batchSize = 5) {
  for (let i = 0; i < items.length; i += batchSize) {
    await Promise.all(items.slice(i, i + batchSize).map(fn));
  }
}

// ── Document API helpers ──────────────────────────────────────────────────────
async function fetchDocuments(envUrl, token, docType) {
  const results = [];
  let nextPageKey = null;
  let useAdmin = true;
  do {
    const filter  = encodeURIComponent(`type=='${docType}'`);
    const adminQs = useAdmin ? '&admin-access=true' : '';
    const base    = `${envUrl}/platform/document/v1/documents?filter=${filter}&page-size=500${adminQs}`;
    const url     = nextPageKey ? `${base}&page-key=${encodeURIComponent(nextPageKey)}` : base;
    let data;
    try {
      data = await dtGet(url, token);
    } catch (e) {
      if (useAdmin && !nextPageKey) {
        useAdmin = false;
        data = await dtGet(`${envUrl}/platform/document/v1/documents?filter=${filter}&page-size=500`, token);
      } else throw e;
    }
    if (!data) break;
    results.push(...(data.documents ?? data.results ?? []));
    nextPageKey = data.nextPageKey ?? null;
  } while (nextPageKey);
  console.log(`  Documents (${docType}): ${results.length} [${useAdmin ? 'admin' : 'user-scope'}]`);
  return { docs: results, useAdmin };
}

async function fetchDocumentContent(envUrl, token, docId, useAdmin) {
  const base = `${envUrl}/platform/document/v1/documents/${encodeURIComponent(docId)}/content`;
  return dtGet(useAdmin ? `${base}?admin-access=true` : base, token);
}

// ── Settings API helper ───────────────────────────────────────────────────────
async function fetchSettingsObjects(schemaId) {
  const results = [];
  let nextPageKey = null;
  do {
    const data = await settingsObjectsClient.getSettingsObjects(
      nextPageKey
        ? { nextPageKey, pageSize: 500 }
        : { schemaIds: schemaId, fields: 'objectId,value,summary', pageSize: 500 },
    );
    if (!data) break;
    results.push(...(data.items ?? []));
    nextPageKey = data.nextPageKey ?? null;
  } while (nextPageKey);
  console.log(`  Settings ${schemaId}: ${results.length}`);
  return results;
}

// ── SLO helper ────────────────────────────────────────────────────────────────
async function fetchPlatformSlos(envUrl, token) {
  const results = [];
  let offset = 0;
  while (true) {
    const data = await dtGet(`${envUrl}/platform/slo/v1/slos?offset=${offset}&limit=500`, token);
    if (!data) break;
    const items = data.slos ?? data.items ?? [];
    results.push(...items);
    if (items.length < 500) break;
    offset += 500;
  }
  console.log(`  Platform SLOs: ${results.length}`);
  return results;
}

// ── Workflow helper ───────────────────────────────────────────────────────────
async function fetchWorkflows(envUrl, token) {
  const results = [];
  let offset = 0;
  while (true) {
    const data = await dtGet(`${envUrl}/platform/automation/v1/workflows?offset=${offset}&limit=500`, token);
    if (!data) break;
    const items = data.results ?? data.items ?? [];
    results.push(...items);
    if (items.length < 500) break;
    offset += 500;
  }
  console.log(`  Workflows: ${results.length}`);
  return results;
}

// ── OpenPipeline helper ───────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
export default async function () {
  const ex     = await execution();
  const params = ex.params ?? {};
  const cfg    = ex.input  ?? {};

  const vaultId = String(params.vaultId ?? cfg.oauth?.credentialId ?? '').trim();
  const cfgUrl  = String(cfg.envUrl ?? '').trim();
  const envUrl  = (cfgUrl && !cfgUrl.toLowerCase().includes('changeme')
    ? cfgUrl : String(getEnvironmentUrl() ?? '')).replace(/\/$/, '');

  if (!vaultId) throw new Error('Missing vaultId');
  const enabledCats = params.enabledCategories ?? {};
  const isCatEnabled = (cat) => enabledCats[cat] !== false;
  if (!envUrl)  throw new Error('Missing envUrl');
  console.log('envUrl:', envUrl);

  const details = await credentialVaultClient.getCredentialsDetails({ id: vaultId });
  const tokenResp = await fetch(TOKEN_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json' },
    body: new URLSearchParams({
      grant_type:    'client_credentials',
      client_id:     details.username,
      client_secret: details.password,
      scope:         REQUIRED_SCOPES,
    }).toString(),
  });
  if (!tokenResp.ok) throw new Error(`Token failed: ${tokenResp.status}`);
  const token = String((await tokenResp.json()).access_token ?? '').trim();
  if (!token) throw new Error('OAuth: empty access_token');
  console.log('Token acquired');

  const timestamp    = new Date().toISOString();
  const summaryStats = [];
  const errors       = [];

  // ── 1. Dashboards ───────────────────────────────────────────────────────────
  if (isCatEnabled('dashboard')) {
  try {
    console.log('Processing: dashboards');
    const { docs, useAdmin } = await fetchDocuments(envUrl, token, 'dashboard');
    const retained = [];
    const stats    = emptyStats();
    stats.analyzed = docs.length;
    await batchProcess(docs, async (doc) => {
      let content;
      try { content = await fetchDocumentContent(envUrl, token, doc.id, useAdmin); }
      catch (e) { stats.errorCount++; errors.push(`dashboard:${doc.id}: ${e.message}`); return; }
      if (!content) return;
      const record = buildRecord('dashboard', doc.id, doc.name ?? doc.id, content, timestamp);
      content = null;
      trackRecord(stats, record);
      if (record.filter_count > 0) retained.push(record);
    });
    await uploadLookup(retained.length > 0 ? retained : [buildSentinel('dashboard', timestamp)], 'dashboard');
    summaryStats.push(buildSummaryRecord('dashboard', stats, timestamp));
  } catch (e) {
    errors.push(`dashboard: ${e.message}`);
    await uploadLookup([buildSentinel('dashboard', timestamp)], 'dashboard').catch(() => {});
    summaryStats.push(buildSummaryRecord('dashboard', { ...emptyStats(), errorCount: 1 }, timestamp));
  }
  } else {
    console.log('Skipping: dashboard (disabled)');
  }

  // ── 2. Notebooks ────────────────────────────────────────────────────────────
  if (isCatEnabled('notebook')) {
  try {
    console.log('Processing: notebooks');
    const { docs, useAdmin } = await fetchDocuments(envUrl, token, 'notebook');
    const retained = [];
    const stats    = emptyStats();
    stats.analyzed = docs.length;
    await batchProcess(docs, async (doc) => {
      let content;
      try { content = await fetchDocumentContent(envUrl, token, doc.id, useAdmin); }
      catch (e) { stats.errorCount++; errors.push(`notebook:${doc.id}: ${e.message}`); return; }
      if (!content) return;
      const record = buildRecord('notebook', doc.id, doc.name ?? doc.id, content, timestamp);
      content = null;
      trackRecord(stats, record);
      if (record.filter_count > 0) retained.push(record);
    });
    await uploadLookup(retained.length > 0 ? retained : [buildSentinel('notebook', timestamp)], 'notebook');
    summaryStats.push(buildSummaryRecord('notebook', stats, timestamp));
  } catch (e) {
    errors.push(`notebook: ${e.message}`);
    await uploadLookup([buildSentinel('notebook', timestamp)], 'notebook').catch(() => {});
    summaryStats.push(buildSummaryRecord('notebook', { ...emptyStats(), errorCount: 1 }, timestamp));
  }
  } else {
    console.log('Skipping: notebook (disabled)');
  }

  // ── 3. Anomaly Detection ────────────────────────────────────────────────────
  if (isCatEnabled('anomaly-detection')) {
  try {
    console.log('Processing: anomaly-detection');
    const [metricEvents, davisDetectors] = await Promise.all([
      fetchSettingsObjects('builtin:anomaly-detection.metric-events'),
      fetchSettingsObjects('builtin:davis.anomaly-detectors'),
    ]);
    const all      = [...metricEvents, ...davisDetectors];
    const retained = [];
    const stats    = emptyStats();
    for (const item of all) {
      stats.analyzed++;
      try {
        const id   = item.objectId ?? item.id ?? '';
        const name = item.summary ?? item.value?.displayName ?? item.value?.name ?? id;
        const record = buildRecord('anomaly-detection', id, name, item.value ?? item, timestamp);
        trackRecord(stats, record);
        if (record.filter_count > 0) retained.push(record);
      } catch (e) {
        stats.errorCount++;
        errors.push(`anomaly-detection:${item.objectId}: ${e.message}`);
      }
    }
    await uploadLookup(retained.length > 0 ? retained : [buildSentinel('anomaly-detection', timestamp)], 'anomaly-detection');
    summaryStats.push(buildSummaryRecord('anomaly-detection', stats, timestamp));
  } catch (e) {
    errors.push(`anomaly-detection: ${e.message}`);
    await uploadLookup([buildSentinel('anomaly-detection', timestamp)], 'anomaly-detection').catch(() => {});
    summaryStats.push(buildSummaryRecord('anomaly-detection', { ...emptyStats(), errorCount: 1 }, timestamp));
  }
  } else {
    console.log('Skipping: anomaly-detection (disabled)');
  }

  // ── 4. SLOs ─────────────────────────────────────────────────────────────────
  if (isCatEnabled('slo')) {
  try {
    console.log('Processing: slos');
    const [platformSlos, settingsSlos] = await Promise.all([
      fetchPlatformSlos(envUrl, token),
      fetchSettingsObjects('builtin:monitoring.slo'),
    ]);
    const retained = [];
    const stats    = emptyStats();
    for (const slo of platformSlos) {
      stats.analyzed++;
      try {
        const record = buildRecord('slo', slo.id ?? '', slo.name ?? slo.title ?? slo.id ?? '', slo, timestamp);
        trackRecord(stats, record);
        if (record.filter_count > 0) retained.push(record);
      } catch (e) { stats.errorCount++; errors.push(`slo:${slo.id}: ${e.message}`); }
    }
    for (const item of settingsSlos) {
      stats.analyzed++;
      try {
        const id   = item.objectId ?? item.id ?? '';
        const name = item.summary ?? item.value?.name ?? item.value?.displayName ?? id;
        const record = buildRecord('slo', id, name, item.value ?? item, timestamp);
        trackRecord(stats, record);
        if (record.filter_count > 0) retained.push(record);
      } catch (e) { stats.errorCount++; errors.push(`slo:${item.objectId}: ${e.message}`); }
    }
    await uploadLookup(retained.length > 0 ? retained : [buildSentinel('slo', timestamp)], 'slo');
    summaryStats.push(buildSummaryRecord('slo', stats, timestamp));
  } catch (e) {
    errors.push(`slo: ${e.message}`);
    await uploadLookup([buildSentinel('slo', timestamp)], 'slo').catch(() => {});
    summaryStats.push(buildSummaryRecord('slo', { ...emptyStats(), errorCount: 1 }, timestamp));
  }
  } else {
    console.log('Skipping: slo (disabled)');
  }

  // ── 5. SRE Guardians ────────────────────────────────────────────────────────
  if (isCatEnabled('sre')) {
  try {
    console.log('Processing: sre');
    const items    = await fetchSettingsObjects('app:dynatrace.site.reliability.guardian:guardians');
    const retained = [];
    const stats    = emptyStats();
    for (const item of items) {
      stats.analyzed++;
      try {
        const id   = item.objectId ?? item.id ?? '';
        const name = item.summary ?? item.value?.name ?? item.value?.displayName ?? id;
        const record = buildRecord('sre', id, name, item.value ?? item, timestamp);
        trackRecord(stats, record);
        if (record.filter_count > 0) retained.push(record);
      } catch (e) { stats.errorCount++; errors.push(`sre:${item.objectId}: ${e.message}`); }
    }
    await uploadLookup(retained.length > 0 ? retained : [buildSentinel('sre', timestamp)], 'sre');
    summaryStats.push(buildSummaryRecord('sre', stats, timestamp));
  } catch (e) {
    errors.push(`sre: ${e.message}`);
    await uploadLookup([buildSentinel('sre', timestamp)], 'sre').catch(() => {});
    summaryStats.push(buildSummaryRecord('sre', { ...emptyStats(), errorCount: 1 }, timestamp));
  }
  } else {
    console.log('Skipping: sre (disabled)');
  }

  // ── 6. Workflows (filter + matcher) ─────────────────────────────────────────
  if (isCatEnabled('workflow')) {
  try {
    console.log('Processing: workflows');
    const items    = await fetchWorkflows(envUrl, token);
    const retained = [];
    const stats    = emptyStats();
    for (const wf of items) {
      stats.analyzed++;
      try {
        const id     = wf.id ?? '';
        const name   = wf.title ?? wf.name ?? id;
        const record = buildRecord('workflow', id, name, wf, timestamp, true); // includeMatchers
        trackRecord(stats, record);
        if (record.filter_count > 0) retained.push(record);
      } catch (e) { stats.errorCount++; errors.push(`workflow:${wf.id}: ${e.message}`); }
    }
    await uploadLookup(retained.length > 0 ? retained : [buildSentinel('workflow', timestamp)], 'workflow');
    summaryStats.push(buildSummaryRecord('workflow', stats, timestamp));
  } catch (e) {
    errors.push(`workflow: ${e.message}`);
    await uploadLookup([buildSentinel('workflow', timestamp)], 'workflow').catch(() => {});
    summaryStats.push(buildSummaryRecord('workflow', { ...emptyStats(), errorCount: 1 }, timestamp));
  }
  } else {
    console.log('Skipping: workflow (disabled)');
  }

  // ── 7. OpenPipeline (filter + matcher) ──────────────────────────────────────
  if (isCatEnabled('openpipeline')) {
  try {
    console.log('Processing: openpipeline');
    const OPENPIPELINE_SCHEMAS = [
      'builtin:openpipeline.logs.pipelines',
      'builtin:openpipeline.logs.routing',
      'builtin:openpipeline.logs.ingest-sources',
      'builtin:openpipeline.events.pipelines',
      'builtin:openpipeline.events.routing',
      'builtin:openpipeline.events.ingest-sources',
      'builtin:openpipeline.spans.pipelines',
    ];
    const retained = [];
    const stats    = emptyStats();
    for (const schemaId of OPENPIPELINE_SCHEMAS) {
      const items = await fetchSettingsObjects(schemaId);
      for (const item of items) {
        stats.analyzed++;
        try {
          const id   = item.objectId ?? item.id ?? '';
          const name = item.summary ?? item.value?.displayName ?? item.value?.name ?? schemaId;
          const record = buildRecord('openpipeline', id, name, item.value ?? item, timestamp, true);
          trackRecord(stats, record);
          if (record.filter_count > 0) retained.push(record);
        } catch (e) { stats.errorCount++; errors.push(`openpipeline:${item.objectId}: ${e.message}`); }
      }
    }
    await uploadLookup(retained.length > 0 ? retained : [buildSentinel('openpipeline', timestamp)], 'openpipeline');
    summaryStats.push(buildSummaryRecord('openpipeline', stats, timestamp));
  } catch (e) {
    errors.push(`openpipeline: ${e.message}`);
    await uploadLookup([buildSentinel('openpipeline', timestamp)], 'openpipeline').catch(() => {});
    summaryStats.push(buildSummaryRecord('openpipeline', { ...emptyStats(), errorCount: 1 }, timestamp));
  }
  } else {
    console.log('Skipping: openpipeline (disabled)');
  }

  // ── Summary — merge new results with preserved records for skipped categories ─
  try {
    let mergedStats = summaryStats;
    try {
      const existing = await readSummary(envUrl, token);
      if (existing.length > 0) {
        const scannedCats = new Set(summaryStats.map(r => r.configuration_type));
        const preserved   = existing.filter(r => r.configuration_type && !scannedCats.has(r.configuration_type));
        if (preserved.length > 0) {
          mergedStats = [...summaryStats, ...preserved];
          console.log(`Preserved ${preserved.length} skipped-category record(s) in summary`);
        }
      }
    } catch (e) {
      console.warn('Could not read existing summary for merge (will overwrite):', e.message);
    }
    await uploadSummary(mergedStats);
  } catch (e) {
    console.error('Summary upload failed:', e.message);
  }

  const totalAnalyzed = summaryStats.reduce((s, r) => s + r.total_analyzed, 0);
  const totalWithFilters = summaryStats.reduce((s, r) => s + r.with_filters, 0);
  console.log(`Scan complete: ${totalAnalyzed} analyzed, ${totalWithFilters} with filters, ${errors.length} errors`);

  return {
    scan_timestamp:     timestamp,
    total_analyzed:     totalAnalyzed,
    with_filters:       totalWithFilters,
    total_errors:       errors.length,
    error_details:      errors,
  };
}
